package dev.darcosse.common.cobblemonsafari.park;

import java.util.List;

/**
 * Where the Safari island lies, its world border, its arrival point and its
 * rest houses, in blocks. GENERATED by tools/worldgen/generate_worldgen.py
 * from the terrain it generates: edit the constants there and run it, never
 * this file, or the border and the arrival no longer match the island.
 */
public final class ParkGeometry {

    /** Centre of the island and of the world border. */
    public static final int CENTER_X = 0;
    public static final int CENTER_Z = 0;

    /** Half the side of the square world border: the island plus a strip of lagoon. */
    public static final int BORDER_HALF_SIZE = 868;

    /** Arrival point: in the grassland north of the centre, like the entrance of the games' Safari Zones. */
    public static final int ARRIVAL_X = 0;
    public static final int ARRIVAL_Z = -422;

    /** Arrivals are spread this far around the arrival point, so a group does not land on one block. */
    public static final int ARRIVAL_SPREAD = 16;

    /**
     * Anchors of the rest houses, entrance first: each house is built at the
     * best spot near its anchor. The anchor also identifies the house in the
     * saved world state, so changing one builds a new house there on the
     * next map.
     */
    public static final List<Column> REST_HOUSES = List.of(
            new Column(0, -436),
            new Column(422, 0),
            new Column(0, 422),
            new Column(-422, 0),
            new Column(298, -298),
            new Column(298, 298),
            new Column(-298, 298),
            new Column(-298, -298)
    );

    /**
     * Rest houses underground, one per cavern, each in a chamber dug beside
     * its cavern's passage (structure.CaveChamber). Fixed positions: no site
     * search, the chamber is dug whatever the rock. Also identified in the
     * saved world state by their column, after the surface anchors.
     */
    public static final List<CaveHouse> CAVE_REST_HOUSES = List.of(
            new CaveHouse("giant_cavern", 0, 28, 34, 0, -0.25, 18),
            new CaveHouse("lush_cavern", 0, 32, 341, 307, 0.25, 18)
    );

    /** A column of the park, x and z in blocks. */
    public record Column(int x, int z) {
    }

    /**
     * An underground rest house and the passage its chamber opens on.
     *
     * @param id            name of the cavern, as dialogue functions and translation keys write it
     * @param x             centre column of the house
     * @param groundY       height of the house's ground layer: players walk out at groundY + 1
     * @param z             centre column of the house
     * @param passageZ      z of the passage's axis, which runs along x past the house's door
     * @param passageRise   blocks the passage's floor climbs per block toward +x
     * @param passageReach  how far, in blocks, the passage's walls can stray from its axis
     */
    public record CaveHouse(String id, int x, int groundY, int z, int passageZ, double passageRise,
                            int passageReach) {
    }

    private ParkGeometry() {
    }
}
